using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Linq;using System.Net.NetworkInformation;using System.Runtime.InteropServices;using System.Text;using System.Threading;using System.Threading.Tasks;using Windows.Foundation;using Windows.Media;using Windows.Media.Control;
namespace Iris {
    public static class ProviderMedia {
        public static bool Matches(string source,string provider){if(string.IsNullOrEmpty(source))return false;return provider=="applemusic"?source.StartsWith("AppleInc.AppleMusicWin_",StringComparison.OrdinalIgnoreCase)||string.Equals(source,"AppleMusic.exe",StringComparison.OrdinalIgnoreCase)||string.Equals(source,"AppleMusic",StringComparison.OrdinalIgnoreCase):source.StartsWith("SpotifyAB.SpotifyMusic_",StringComparison.OrdinalIgnoreCase)||string.Equals(source,"Spotify.exe",StringComparison.OrdinalIgnoreCase)||string.Equals(source,"Spotify",StringComparison.OrdinalIgnoreCase);}
        static T Wait<T>(IAsyncOperation<T> operation,CancellationToken token){var done=new TaskCompletionSource<T>();operation.Completed=delegate{try{done.TrySetResult(operation.GetResults());}catch(Exception ex){done.TrySetException(ex);}};try{if(!done.Task.Wait(4500,token))throw new TimeoutException(L.T("Die Medienquelle antwortet nicht rechtzeitig."));return done.Task.GetAwaiter().GetResult();}finally{if(operation.Status==AsyncStatus.Started)operation.Cancel();}}
        public static AddonResult Execute(string provider,string operation,CancellationToken token){var manager=Wait(GlobalSystemMediaTransportControlsSessionManager.RequestAsync(),token);var sessions=manager.GetSessions().Where(s=>Matches(s.SourceAppUserModelId,provider)).ToArray();var current=manager.GetCurrentSession();var session=current!=null&&sessions.Any(s=>s.SourceAppUserModelId==current.SourceAppUserModelId)?current:sessions.Length==1?sessions[0]:null;if(session==null)throw new InvalidOperationException(sessions.Length>1?L.T("Mehrere passende Mediensitzungen. Gewünschte Quelle zuerst in der App aktivieren."):L.T("Keine passende Mediensitzung. In der gewünschten App zuerst einen Titel auswählen."));
            var info=session.GetPlaybackInfo();var controls=info.Controls;if(operation=="info"){var properties=Wait(session.TryGetMediaPropertiesAsync(),token);return AddonResult.State(properties.Title+"\n"+properties.Artist+"\n"+properties.AlbumTitle+"\n"+info.PlaybackStatus+"\n"+session.SourceAppUserModelId,L.T("Medieninformationen gelesen"));}
            bool accepted=false;
            if(operation=="toggle"&&controls.IsPlayPauseToggleEnabled)accepted=Wait(session.TryTogglePlayPauseAsync(),token);
            else if(operation=="next"&&controls.IsNextEnabled)accepted=Wait(session.TrySkipNextAsync(),token);
            else if(operation=="previous"&&controls.IsPreviousEnabled)accepted=Wait(session.TrySkipPreviousAsync(),token);
            else if(operation=="shuffle"&&controls.IsShuffleEnabled){if(!info.IsShuffleActive.HasValue)throw new InvalidOperationException(L.T("Die Quelle meldet keinen lesbaren Shuffle-Zustand."));accepted=Wait(session.TryChangeShuffleActiveAsync(!info.IsShuffleActive.Value),token);}
            else if(operation=="repeat"&&controls.IsRepeatEnabled){if(!info.AutoRepeatMode.HasValue)throw new InvalidOperationException(L.T("Die Quelle meldet keinen lesbaren Wiederholungszustand."));var next=info.AutoRepeatMode.Value==MediaPlaybackAutoRepeatMode.None?MediaPlaybackAutoRepeatMode.List:info.AutoRepeatMode.Value==MediaPlaybackAutoRepeatMode.List?MediaPlaybackAutoRepeatMode.Track:MediaPlaybackAutoRepeatMode.None;accepted=Wait(session.TryChangeAutoRepeatModeAsync(next),token);}
            if(!accepted)throw new InvalidOperationException(L.T("Diese Medienquelle bietet den Befehl über Windows gerade nicht an. Bei Spotify sind zusätzlich die Connect-Aktionen verfügbar."));return AddonResult.Of(AddonResultCode.Succeeded,L.T("Befehl von der passenden Medienquelle angenommen."));
        }
        public static void Open(string provider,CancellationToken token,Action<string,string,string> launch){if(provider=="spotify"){launch("spotify:","","");return;}object shell=null,folder=null,items=null;try{shell=Activator.CreateInstance(Type.GetTypeFromProgID("Shell.Application"));folder=Call(shell,"NameSpace",System.Reflection.BindingFlags.InvokeMethod,"shell:AppsFolder");items=Call(folder,"Items",System.Reflection.BindingFlags.InvokeMethod);int count=Math.Min(1024,Convert.ToInt32(Call(items,"Count",System.Reflection.BindingFlags.GetProperty)));for(int i=0;i<count;i++){token.ThrowIfCancellationRequested();object item=null;try{item=Call(items,"Item",System.Reflection.BindingFlags.InvokeMethod,i);string path=Convert.ToString(Call(item,"Path",System.Reflection.BindingFlags.GetProperty));if(System.Text.RegularExpressions.Regex.IsMatch(path??"",@"^AppleInc\.AppleMusicWin_[A-Za-z0-9._-]+![A-Za-z0-9._-]+$")){launch(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"explorer.exe"),"shell:AppsFolder\\"+path,"");return;}}finally{Release(item);}}}finally{Release(items);Release(folder);Release(shell);}throw new InvalidOperationException(L.T("Apple Music nicht im Windows-Appkatalog gefunden. App installieren oder starten."));}
        static object Call(object obj,string name,System.Reflection.BindingFlags flags,params object[] args){return obj.GetType().InvokeMember(name,flags,null,obj,args);}
        static void Release(object obj){if(obj!=null&&Marshal.IsComObject(obj))Marshal.ReleaseComObject(obj);}
    }
    public sealed partial class NativeAddonHost {
        public string IntegrationDirectory;public Func<AddonAction,AddonResult> LocalIntegration;
        AddonResult ExecuteIntegration(AddonDefinition d,AddonAction a,AddonExecutionContext context,CancellationToken token){
            if(d.Confirm&&!context.Confirmed)return AddonResult.Of(AddonResultCode.ConfirmationRequired,d.Description);
            if(a.Kind=="spotify-connect"){new SpotifyApi(IntegrationDirectory).Connect(uri=>Launch(uri,"",""),token);return AddonResult.Of(AddonResultCode.Succeeded,L.T("Spotify-Anmeldung gespeichert. Token wird für dieses Windows-Konto verschlüsselt."));}
            if(a.Kind.StartsWith("spotify-")&&new[]{"api-shuffle","api-repeat","like","devices","play-context","device"}.Contains(a.Kind.Substring(8)))return SpotifyActions.Execute(new SpotifyApi(IntegrationDirectory),a,token);
            if(a.Kind.StartsWith("obs-")){var c=AddonConnectionStore.Read(IntegrationDirectory);using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(token)){timeout.CancelAfter(10000);using(var socket=new ObsSocket(c.ObsEndpoint,timeout.Token))return new ObsConnection(socket,c.ObsPassword,timeout.Token).Execute(a,timeout.Token);}}
            if(a.Kind=="hardware-snapshot")return AddonResult.State(HardwareReading.Read(token),L.T("Messung gelesen"));
            if(a.Kind.StartsWith("coding-"))return CodingAction(a,token);
            if(a.Kind=="browser-open"||a.Kind=="spotify-playlist"||a.Kind=="applemusic-playlist"){Launch(a.Target,"","");return AddonResult.Of(AddonResultCode.Succeeded,L.T("Link geöffnet; Wiedergabe nicht automatisch gestartet."));}
            if(a.Kind=="productivity-note"){if(!File.Exists(a.Target))throw new FileNotFoundException(L.T("Notizdatei nicht gefunden."));Launch(a.Target,"","");return AddonResult.Of(AddonResultCode.Succeeded,L.T("Notizdatei geöffnet."));}
            if(a.Kind.StartsWith("spotify-")||a.Kind.StartsWith("applemusic-")){string provider=a.Kind.StartsWith("spotify-")?"spotify":"applemusic",op=a.Kind.Substring(provider.Length+1);if(op=="open"){ProviderMedia.Open(provider,token,Launch);return AddonResult.Of(AddonResultCode.Succeeded,L.T("App-Start angefordert."));}if(op=="search"){Launch(provider=="spotify"?"spotify:search:"+Uri.EscapeDataString(a.Target):"https://music.apple.com/de/search?term="+Uri.EscapeDataString(a.Target),"","");return AddonResult.Of(AddonResultCode.Succeeded,L.T("Suche geöffnet."));}if(op!="player"&&!op.StartsWith("volume-")&&op!="mute")return ProviderMedia.Execute(provider,op,token);}
            if(LocalIntegration==null)throw new InvalidOperationException(L.T("Die Iris-Oberfläche ist nicht verfügbar."));token.ThrowIfCancellationRequested();return LocalIntegration(a);
        }
        public static string QuoteArgument(string value){if(value==null)return "\"\"";return "\""+System.Text.RegularExpressions.Regex.Replace(value,@"(\\*)\""",m=>m.Groups[1].Value+m.Groups[1].Value+"\\\"").TrimEnd('\\')+new string('\\',value.Reverse().TakeWhile(c=>c=='\\').Count()*2)+"\"";}
        public static string FindTool(string name){if(Path.GetFileName(name)!=name||Path.GetExtension(name)!=".exe")throw new InvalidOperationException(L.T("Ungültiger Werkzeugname."));foreach(string item in (Environment.GetEnvironmentVariable("PATH")??"").Split(';')){try{string directory=Environment.ExpandEnvironmentVariables(item.Trim(' ','\"'));if(!Path.IsPathRooted(directory))continue;string file=Path.Combine(directory,name);if(File.Exists(file))return file;}catch{}}if(name=="git.exe"){string file=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"Git","cmd",name);if(File.Exists(file))return file;}if(name=="dotnet.exe"){string file=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"dotnet",name);if(File.Exists(file))return file;}throw new FileNotFoundException(name+L.T(" ist nicht installiert oder nicht im Suchpfad."));}
        AddonResult CodingAction(AddonAction a,CancellationToken token){if(!Directory.Exists(a.Target))throw new DirectoryNotFoundException(L.T("Projektordner nicht gefunden."));string op=a.Kind.Substring(7);if(op=="folder"){Folder(a.Target);return AddonResult.Of(AddonResultCode.Succeeded,L.T("Projektordner geöffnet."));}if(op=="project"){Launch("vscode://file/"+a.Target.Replace('\\','/').Split('/').Select(Uri.EscapeDataString).Aggregate((x,y)=>x+"/"+y),"","");return AddonResult.Of(AddonResultCode.Succeeded,L.T("Projektöffnung in VS Code angefordert."));}if(op=="terminal"){Launch(FindTool("wt.exe"),"-d "+QuoteArgument(a.Target),a.Target);return AddonResult.Of(AddonResultCode.Succeeded,L.T("Windows-Terminal geöffnet."));}string logDirectory=Path.Combine(IntegrationDirectory,"ActionLogs");string log=Path.Combine(logDirectory,"last-coding.txt");if(op=="logs"){if(!File.Exists(log))return AddonResult.Of(AddonResultCode.Succeeded,L.T("Noch kein Build-/Git-Protokoll vorhanden."));return AddonResult.Of(AddonResultCode.Succeeded,File.ReadAllText(log));}
            string tool=op.StartsWith("git-")?FindTool("git.exe"):FindTool("dotnet.exe");string arguments=op=="git-status"?"status --short --branch":op=="git-pull"?"pull --ff-only":op=="git-push"?"push":op=="build"?"build --nologo":op=="test"?"test --nologo":null;if(arguments==null)throw new InvalidOperationException(L.T("Unbekannte Coding-Aktion."));Directory.CreateDirectory(logDirectory);var buffer=new StringBuilder();object gate=new object();using(var process=new Process{StartInfo=new ProcessStartInfo(tool,arguments){WorkingDirectory=a.Target,UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true}}){DataReceivedEventHandler receive=delegate(object sender,DataReceivedEventArgs e){if(e.Data!=null)lock(gate){buffer.AppendLine(e.Data);if(buffer.Length>48000)buffer.Remove(0,buffer.Length-40000);}};process.OutputDataReceived+=receive;process.ErrorDataReceived+=receive;token.ThrowIfCancellationRequested();process.Start();process.BeginOutputReadLine();process.BeginErrorReadLine();var clock=Stopwatch.StartNew();while(!process.WaitForExit(100)){if(token.IsCancellationRequested||clock.Elapsed.TotalMinutes>5){lock(gate)File.WriteAllText(log,buffer.ToString()+L.T("\nWarten beendet; der bereits gestartete Prozess kann weiterlaufen. PID ")+process.Id);token.ThrowIfCancellationRequested();throw new TimeoutException(L.T("Werkzeug läuft länger als fünf Minuten. Es wurde nicht zwangsweise beendet; PID ")+process.Id+L.T(". Protokoll unter ActionLogs."));}}process.WaitForExit();string text;lock(gate)text=buffer.ToString();File.WriteAllText(log,DateTime.Now+" · "+a.Target+"\n"+Path.GetFileName(tool)+" "+arguments+"\nExit "+process.ExitCode+"\n"+text);if(text.Length>12000)text=text.Substring(text.Length-12000);return AddonResult.Of(process.ExitCode==0?AddonResultCode.Succeeded:AddonResultCode.Failed,"Exit "+process.ExitCode+"\n"+text+L.T("\nVollständiges begrenztes Protokoll: ")+log);}
        }
    }
    public static class HardwareReading {
        [StructLayout(LayoutKind.Sequential)]struct Memory {public uint Length,Load;public ulong Total,Available,PageTotal,PageAvailable,VirtualTotal,VirtualAvailable,Extended;}
        [DllImport("kernel32.dll")]static extern bool GlobalMemoryStatusEx(ref Memory memory);
        [DllImport("kernel32.dll")]static extern bool GetSystemTimes(out long idle,out long kernel,out long user);
        static long Network(){long total=0;foreach(var n in NetworkInterface.GetAllNetworkInterfaces())if(n.OperationalStatus==OperationalStatus.Up&&n.NetworkInterfaceType!=NetworkInterfaceType.Loopback){var s=n.GetIPv4Statistics();total+=s.BytesReceived+s.BytesSent;}return total;}
        public static string Read(CancellationToken token){long idle1,k1,u1,idle2,k2,u2;if(!GetSystemTimes(out idle1,out k1,out u1))throw new InvalidOperationException(L.T("CPU-Messung nicht verfügbar."));long network1=Network();var time=Stopwatch.StartNew();if(token.WaitHandle.WaitOne(450))token.ThrowIfCancellationRequested();if(!GetSystemTimes(out idle2,out k2,out u2))throw new InvalidOperationException(L.T("CPU-Messung fehlgeschlagen."));long network2=Network();double elapsed=time.Elapsed.TotalSeconds,total=k2-k1+u2-u1;var memory=new Memory{Length=(uint)Marshal.SizeOf(typeof(Memory))};bool known=GlobalMemoryStatusEx(ref memory);var text=new StringBuilder(L.T("Messung · ")+DateTime.Now.ToString("HH:mm:ss")+"\n");text.AppendLine(total>0?"CPU: "+Math.Round(100*(1-(idle2-idle1)/total))+" %":L.T("CPU: nicht verfügbar"));text.AppendLine(known?"RAM: "+((memory.Total-memory.Available)/1073741824d).ToString("F1")+" / "+(memory.Total/1073741824d).ToString("F1")+" GB":L.T("RAM: nicht verfügbar"));text.AppendLine(L.T("Netzwerk gesamt: ")+(Math.Max(0,network2-network1)/elapsed/1048576).ToString("F2")+" MiB/s");foreach(var drive in DriveInfo.GetDrives())try{if(drive.IsReady&&drive.DriveType==DriveType.Fixed)text.AppendLine(drive.Name+" · frei "+(drive.AvailableFreeSpace/1073741824d).ToString("F1")+" / "+(drive.TotalSize/1073741824d).ToString("F1")+" GB");}catch{}text.AppendLine(L.T("GPU/Temperatur/Lüfter: ohne angebundenen Sensor nicht verfügbar. Spiel-FPS: unter Gaming."));return text.ToString();}
    }
}
